// Navigation
function toggleNav(){document.getElementById('mobileNav').classList.toggle('open')}

// Scroll shadow on nav
(function(){
  const nav=document.querySelector('.nav');
  window.addEventListener('scroll',function(){
    nav.style.boxShadow=window.scrollY>8?'0 1px 12px rgba(0,0,0,.1)':'none';
  });
})();

// Fade-in on scroll
(function(){
  const els=document.querySelectorAll('.feat-card,.stat,.section-hd');
  if(!('IntersectionObserver' in window)){
    els.forEach(function(el){el.classList.add('fadein','visible')});return;
  }
  els.forEach(function(el){el.classList.add('fadein')});
  const obs=new IntersectionObserver(function(entries){
    entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}});
  },{threshold:0.1});
  els.forEach(function(el){obs.observe(el)});
})();

// CTA form
function submitCTA(e){
  e.preventDefault();
  var form=e.target;
  var success=document.getElementById('ctaSuccess');
  form.style.display='none';
  success.style.display='block';
}

/* ── Design tokens ──────────────────────────────── */
:root {
  --bg:           #ffffff;
  --surface:      #fafafa;
  --text:         #262626;
  --text-2:       #8e8e8e;
  --text-3:       #c7c7c7;
  --border:       #dbdbdb;
  --accent:       #0095f6;
  --accent-h:     #1877f2;
  --accent-light: #e8f0fe;
  --btn-text:     #fff;
  --shadow:       rgba(0,0,0,.08);
  --hero-grad:    linear-gradient(160deg,#ffffff 40%,#fafafa 100%);
  --cta-bg:       #262626;
  --cta-fg:       #fafafa;
  --radius:       8px;
  --font:         -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;
  --max-w:        975px;
  --ig-gradient:  linear-gradient(45deg,#f09433,#e6683c,#dc2743,#cc2366,#bc1888);
}

/* ── Reset ─────────────────────────────────────── */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{font-size:16px;scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--surface);line-height:1.5;-webkit-font-smoothing:antialiased}
a{text-decoration:none;color:inherit}
img{max-width:100%;display:block}

/* ── Layout ────────────────────────────────────── */
.container{max-width:var(--max-w);margin:0 auto;padding:0 20px}

/* ── Buttons ───────────────────────────────────── */
.btn{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 16px;border-radius:8px;font-size:.875rem;font-weight:600;cursor:pointer;border:none;transition:background .15s,box-shadow .15s,opacity .15s;white-space:nowrap;font-family:inherit}
.btn-primary{background:var(--accent);color:var(--btn-text)}
.btn-primary:hover{background:var(--accent-h);opacity:.9}
.btn-outline{border:1px solid var(--border);color:var(--text);background:var(--bg)}
.btn-outline:hover{background:var(--surface)}
.btn-lg{height:44px;padding:0 24px;font-size:.9375rem;border-radius:8px}
.btn-cta{background:var(--accent);color:var(--btn-text);height:44px;padding:0 24px;border-radius:8px;font-size:.9375rem;font-weight:600;border:none;cursor:pointer;transition:background .15s,opacity .15s;font-family:inherit}
.btn-cta:hover{background:var(--accent-h);opacity:.9}

/* ── Navigation ────────────────────────────────── */
.nav{position:sticky;top:0;z-index:100;background:var(--bg);border-bottom:1px solid var(--border);height:60px;display:flex;flex-direction:column;justify-content:center}
.nav-inner{max-width:var(--max-w);margin:0 auto;padding:0 20px;display:flex;align-items:center;justify-content:space-between;gap:24px;width:100%}
.logo{font-size:1.4rem;font-weight:400;color:var(--text);font-family:'Segoe Script','Brush Script MT','Lucida Handwriting',cursive;letter-spacing:.01em}
.nav-links{display:flex;align-items:center;gap:20px}
.nav-links a{font-size:.875rem;color:var(--text);font-weight:400;transition:color .15s}
.nav-links a:hover{color:var(--accent)}
.nav-links .btn{margin-left:4px}
.hamburger{display:none;flex-direction:column;gap:5px;background:none;border:none;cursor:pointer;padding:4px}
.hamburger span{display:block;width:22px;height:2px;background:var(--text);border-radius:2px;transition:background .15s}
.mobile-nav{display:none;flex-direction:column;gap:14px;padding:14px 20px;border-top:1px solid var(--border);background:var(--bg)}
.mobile-nav a{font-size:.9375rem;color:var(--text);font-weight:400;padding:4px 0}
.mobile-nav.open{display:flex}

/* ── Hero ──────────────────────────────────────── */
.hero{padding:80px 0 72px;text-align:center;background:var(--bg);border-bottom:1px solid var(--border)}
.badge{display:inline-block;margin-bottom:20px;padding:6px 14px;border-radius:4px;background:var(--ig-gradient);font-size:.75rem;font-weight:600;color:#fff;letter-spacing:.06em;text-transform:uppercase;border:none}
h1{font-size:clamp(2rem,5vw,3.5rem);font-weight:300;letter-spacing:-.02em;line-height:1.15;color:var(--text);max-width:680px;margin:0 auto 16px}
.hero-sub{font-size:clamp(.9375rem,2vw,1.0625rem);color:var(--text-2);max-width:480px;margin:0 auto 32px;line-height:1.5;font-weight:400}
.hero-btns{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-bottom:36px}
.proof-row{display:flex;align-items:center;justify-content:center;gap:10px;color:var(--text-2);font-size:.8125rem}
.proof-avatars{display:flex}
.av{width:30px;height:30px;border-radius:50%;background:var(--ig-gradient);color:var(--btn-text);font-size:.6875rem;font-weight:600;display:flex;align-items:center;justify-content:center;border:2px solid var(--bg);margin-left:-8px}
.av:first-child{margin-left:0}
.proof-text strong{color:var(--text)}

/* ── Features ──────────────────────────────────── */
.features{padding:80px 0;background:var(--bg)}
.section-hd{text-align:center;margin-bottom:48px}
.label{font-size:.75rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);margin-bottom:8px}
h2{font-size:clamp(1.5rem,3.5vw,2.25rem);font-weight:300;letter-spacing:-.02em;line-height:1.2;color:var(--text);margin-bottom:10px}
.section-hd p{font-size:.9375rem;color:var(--text-2);max-width:460px;margin:0 auto}
.feat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}
.feat-card{background:var(--bg);border:1px solid var(--border);border-radius:var(--radius);padding:28px 24px;transition:box-shadow .2s,transform .2s}
.feat-card:hover{box-shadow:0 2px 12px var(--shadow);transform:translateY(-1px)}
.feat-num{font-size:1.75rem;font-weight:300;color:var(--accent);opacity:.5;margin-bottom:12px;line-height:1;letter-spacing:-.02em}
.feat-card h3{font-size:1rem;font-weight:600;margin-bottom:8px;color:var(--text)}
.feat-card p{font-size:.875rem;color:var(--text-2);line-height:1.5}

/* ── Stats ─────────────────────────────────────── */
.stats{padding:0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--bg)}
.stats-grid{display:grid;grid-template-columns:repeat(4,1fr)}
.stat{padding:40px 20px;text-align:center;border-right:1px solid var(--border)}
.stat:last-child{border-right:none}
.sv{display:block;font-size:1.75rem;font-weight:300;letter-spacing:-.02em;color:var(--text);line-height:1.1;margin-bottom:4px}
.sl{font-size:.8125rem;color:var(--text-2);font-weight:400}

/* ── CTA section ───────────────────────────────── */
.cta-section{padding:80px 0;background:var(--cta-bg);color:var(--cta-fg);text-align:center}
.cta-inner h2{font-size:clamp(1.5rem,3.5vw,2.25rem);font-weight:300;letter-spacing:-.02em;margin-bottom:10px;color:var(--cta-fg)}
.cta-inner p{font-size:.9375rem;color:rgba(250,250,250,.6);margin-bottom:24px}
.cta-form{display:flex;gap:8px;max-width:440px;margin:0 auto 12px;flex-wrap:wrap;justify-content:center}
.cta-form input[type=email]{flex:1;min-width:200px;height:44px;padding:0 14px;border-radius:6px;border:1px solid rgba(250,250,250,.2);background:rgba(250,250,250,.08);color:var(--cta-fg);font-size:.875rem;outline:none;font-family:inherit;transition:border-color .15s}
.cta-form input::placeholder{color:rgba(250,250,250,.4)}
.cta-form input:focus{border-color:var(--accent)}
.cta-note{font-size:.8125rem;color:rgba(250,250,250,.4)}
.cta-success{margin-top:14px;font-weight:600;color:#4ade80}

/* ── Footer ────────────────────────────────────── */
.footer{background:var(--bg);border-top:1px solid var(--border);padding-top:48px}
.footer-inner{display:flex;justify-content:space-between;gap:40px;flex-wrap:wrap;padding-bottom:40px}
.footer-brand .logo{font-size:1.3rem}
.footer-brand p{margin-top:10px;font-size:.8125rem;color:var(--text-2);max-width:240px;line-height:1.5}
.footer-links{display:flex;gap:40px;flex-wrap:wrap}
.fc{display:flex;flex-direction:column;gap:8px}
.fc p{font-weight:600;font-size:.75rem;color:var(--text);letter-spacing:.04em;text-transform:uppercase;margin-bottom:2px}
.fc a{font-size:.8125rem;color:var(--text-2);transition:color .15s}
.fc a:hover{color:var(--text)}
.footer-btm{border-top:1px solid var(--border);padding:20px 0}
.footer-btm p{font-size:.75rem;color:var(--text-2);text-align:center}

/* ── Fadein animation ──────────────────────────── */
.fadein{opacity:0;transform:translateY(16px);transition:opacity .5s ease,transform .5s ease}
.fadein.visible{opacity:1;transform:translateY(0)}

/* ── Responsive ────────────────────────────────── */
@media(max-width:768px){
  .nav-links{display:none}
  .hamburger{display:flex}
  .hero{padding:60px 0 52px}
  .features{padding:60px 0}
  .cta-section{padding:60px 0}
  .stats-grid{grid-template-columns:repeat(2,1fr)}
  .stat:nth-child(2){border-right:none}
  .stat{border-bottom:1px solid var(--border);padding:32px 16px}
  .stat:nth-child(3),.stat:nth-child(4){border-bottom:none}
  .footer-inner{flex-direction:column;gap:32px}
  .footer-links{gap:32px}
}
@media(max-width:480px){
  .stats-grid{grid-template-columns:1fr}
  .stat{border-right:none;border-bottom:1px solid var(--border)}
  .stat:last-child{border-bottom:none}
  .feat-grid{grid-template-columns:1fr}
}
